import { createClient } from 'supabase';
const sq=(x:number)=>x*x;
Deno.serve(async(req)=>{try{
 const gw=Math.max(1,Math.min(38,Number(new URL(req.url).searchParams.get('gw')||1)));
 const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}'); const key=keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
 const sb=createClient(Deno.env.get('SUPABASE_URL')!,key,{auth:{persistSession:false}});
 const {data:pr,error:pre}=await sb.from('gameweek_prediction_runs').select('*').eq('gameweek',gw).eq('frozen',true).order('generated_at',{ascending:false}).limit(1).maybeSingle(); if(pre)throw pre; if(!pr) return Response.json({ok:false,error:'No frozen prediction run'},{status:404});
 const {data:rr,error:rre}=await sb.from('gameweek_result_runs').select('*').eq('gameweek',gw).order('is_final',{ascending:false}).order('observed_at',{ascending:false}).limit(1).maybeSingle(); if(rre)throw rre; if(!rr) return Response.json({ok:false,error:'No result run'},{status:404});
 const fr=await fetch(`https://fantasy.premierleague.com/api/fixtures/?event=${gw}`,{headers:{'User-Agent':'FootballIntelligence/0.1'}}); if(!fr.ok) throw new Error(`FPL fixtures ${fr.status}`); const fixtures=await fr.json();
 const finished=new Set((fixtures||[]).filter((f:any)=>f.finished===true||f.finished_provisional===true).map((f:any)=>Number(f.id)));
 const [{data:preds,error:pe},{data:acts,error:ae}]=await Promise.all([
   sb.from('model_predictions').select('player_id,expected_minutes,expected_points,p_10_plus,p_15_plus,p_20_plus,p_dc').eq('prediction_run_id',pr.id),
   sb.from('player_gameweek_actuals').select('player_id,fixture_ids,minutes,total_points,defensive_contribution,xg,xa').eq('result_run_id',rr.id)
 ]); if(pe)throw pe;if(ae)throw ae;
 const am=new Map((acts||[]).map((a:any)=>[a.player_id,a])); const rows:any[]=[];
 let saeP=0,sseP=0,saeM=0,b10=0,b15=0,b20=0,bdc=0,c=0,pending=0;
 for(const p of (preds||[])){const a:any=am.get(p.player_id); if(!a)continue; const fids=(a.fixture_ids||[]).map((x:any)=>Number(x)).filter((x:number)=>Number.isFinite(x)); const complete=fids.length>0&&fids.every((id:number)=>finished.has(id)); if(!complete){pending++;continue;} const ap=Number(a.total_points||0), amins=Number(a.minutes||0), ep=Number(p.expected_points||0), em=Number(p.expected_minutes||0); const y10=ap>=10,y15=ap>=15,y20=ap>=20,ydc=Number(a.defensive_contribution||0)>0; const p10=Number(p.p_10_plus||0),p15=Number(p.p_15_plus||0),p20=Number(p.p_20_plus||0),pdc=Number(p.p_dc||0); const me=amins-em, pe2=ap-ep;
   const attribution:any={}; if(Math.abs(me)>=20) attribution.minutes='material'; if(Math.abs(pe2)>=6 && Math.abs(me)<20) attribution.returns_variance='material'; if(ydc!==(pdc>=0.5)) attribution.dc_miss=true;
   rows.push({prediction_run_id:pr.id,result_run_id:rr.id,player_id:p.player_id,gameweek:gw,expected_minutes:em,actual_minutes:amins,minutes_error:me,expected_points:ep,actual_points:ap,points_error:pe2,abs_points_error:Math.abs(pe2),predicted_p10:p10,actual_10_plus:y10,predicted_p15:p15,actual_15_plus:y15,predicted_p20:p20,actual_20_plus:y20,predicted_pdc:pdc,actual_dc:ydc,attribution});
   saeP+=Math.abs(pe2); sseP+=sq(pe2); saeM+=Math.abs(me); b10+=sq(p10-(y10?1:0)); b15+=sq(p15-(y15?1:0)); b20+=sq(p20-(y20?1:0)); bdc+=sq(pdc-(ydc?1:0)); c++;
 }
 const {error:de}=await sb.from('gameweek_model_audits').delete().eq('prediction_run_id',pr.id).eq('result_run_id',rr.id); if(de)throw de;
 for(let k=0;k<rows.length;k+=200){const {error}=await sb.from('gameweek_model_audits').insert(rows.slice(k,k+200));if(error)throw error;}
 const summary={prediction_run_id:pr.id,result_run_id:rr.id,gameweek:gw,players_evaluated:c,mae_points:c?saeP/c:null,rmse_points:c?Math.sqrt(sseP/c):null,mae_minutes:c?saeM/c:null,brier_10:c?b10/c:null,brier_15:c?b15/c:null,brier_20:c?b20/c:null,brier_dc:c?bdc/c:null,calibration:{result_final:rr.is_final,excluded_from_backtest:pr.excluded_from_backtest,eligible_for_cumulative_backtest:Boolean(rr.is_final&&!pr.excluded_from_backtest),pending_players:pending,finished_fixture_ids:[...finished]},notes:rr.is_final?'Final GW audit':'Partial GW audit; only completed player fixtures evaluated'};
 const {error:se}=await sb.from('gameweek_audit_summaries').upsert(summary,{onConflict:'prediction_run_id,result_run_id'});if(se)throw se;
 return Response.json({ok:true,gameweek:gw,prediction_run_id:pr.id,result_run_id:rr.id,result_final:rr.is_final,excluded_from_backtest:pr.excluded_from_backtest,players_evaluated:c,pending_players:pending,summary});
}catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:String(e)},{status:500})}});
